package de.hyprnode.slimy.model

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.InputStream
import java.time.Instant

// Sprite data (generated by tools/make_slime.py into sprites.json). The app
// loads it once from its assets with `SlimeSprites.install(...)`.

/** A small multi-colour sprite (food, coin, furniture …). Palette values are `0xRRGGBB`. */
@Serializable
data class ItemSprite(
    val palette: Map<String, Long>,
    val rows: List<String>,
) {
    /** ARGB colour of one palette character, or null. */
    fun color(key: Char): Long? = palette[key.toString()]?.let { argb(it) }

    val width: Int get() = rows.firstOrNull()?.length ?: 1
    val height: Int get() = rows.size
}

@Serializable
data class AccessorySprite(
    val kind: String,
    val palette: Map<String, Long>,
    val rows: List<String>,
    val island: Long,
)

/**
 * Pixels a skin draws over every frame of the slime: the axolotl's frilly
 * gills and pink cheeks. One grid per frame, in the same order as
 * `SlimeSprites.frames`, with characters from `palette`.
 */
@Serializable
data class SkinOverlaySprite(
    /** The island's font layer for it: Slime-<Stage>-<Anim>-<layer>. */
    val layer: String,
    /** The one colour the island draws the whole overlay in (`0xRRGGBB`). */
    val island: Long,
    val palette: Map<String, Long>,
    val frames: Map<String, List<List<String>>>,
)

object SlimeSprites {
    @Serializable
    data class Bundle(
        val width: Int,
        val height: Int,
        val frames: Map<String, List<List<String>>>,
        val anchors: Map<String, List<List<Int>>>,
        val accessories: Map<String, AccessorySprite>,
        val items: Map<String, ItemSprite>,
        val emoteIcons: Map<String, List<String>>,
        val emoteReels: Map<String, List<String>>,
        /** By skin raw value; only skins with extra pixels are listed. */
        val skinOverlays: Map<String, SkinOverlaySprite>? = null,
    ) {
        companion object {
            val empty = Bundle(
                width = 24, height = 20, frames = emptyMap(), anchors = emptyMap(), accessories = emptyMap(),
                items = emptyMap(), emoteIcons = emptyMap(), emoteReels = emptyMap(), skinOverlays = null,
            )
        }
    }

    private val parser = Json { ignoreUnknownKeys = true }

    /** Reads sprites.json. */
    fun parse(json: String): Bundle = parser.decodeFromString(Bundle.serializer(), json)

    /** Reads sprites.json from a stream (an Android asset); closes it. */
    fun parse(stream: InputStream): Bundle = stream.use { parse(it.readBytes().toString(Charsets.UTF_8)) }

    @Volatile
    private var loaded: Bundle = Bundle.empty

    @Volatile
    private var index: Map<String, Map<List<String>, List<String>>> = emptyMap()

    /** The sprite data in use. Empty until `install` runs. */
    val data: Bundle get() = loaded

    /** Whether real sprite data has been installed. */
    val isLoaded: Boolean get() = loaded.frames.isNotEmpty()

    /** Makes [bundle] the sprite data everything draws from. Call once at startup. */
    @Synchronized
    fun install(bundle: Bundle) {
        index = buildOverlayIndex(bundle)
        loaded = bundle
    }

    val width: Int get() = data.width
    val height: Int get() = data.height
    val items: Map<String, ItemSprite> get() = data.items
    val emoteIcons: Map<String, List<String>> get() = data.emoteIcons
    val emoteReels: Map<String, List<String>> get() = data.emoteReels

    val blank: List<String> = List(20) { ".".repeat(24) }

    fun frames(stage: Stage, anim: SpriteAnim): List<List<String>> =
        data.frames["${stage.name}.${anim.name}"] ?: data.frames["young.idle"] ?: listOf(blank)

    /** Per frame: [head top, eye row, neck row, look offset] (and a sideways slide for `meet`). */
    fun anchors(stage: Stage, anim: SpriteAnim): List<List<Int>> =
        data.anchors["${stage.name}.${anim.name}"] ?: emptyList()

    /** The overlay grid [skin] draws on [frame] (the axolotl's gills and cheeks), or null. */
    fun overlay(skin: Skin, frame: List<String>): List<String>? = index[skin.name]?.get(frame)

    /**
     * Overlay grids by skin, found by the frame they belong to: a renderer
     * only knows its frame's pixels. The generator makes sure frames that
     * look the same get the same overlay.
     */
    private fun buildOverlayIndex(bundle: Bundle): Map<String, Map<List<String>, List<String>>> {
        val out = HashMap<String, Map<List<String>, List<String>>>()
        for ((skin, overlay) in bundle.skinOverlays ?: emptyMap()) {
            val byFrame = HashMap<List<String>, List<String>>()
            for ((key, grids) in overlay.frames) {
                val frames = bundle.frames[key] ?: continue
                for ((frame, grid) in frames.zip(grids)) if (!byFrame.containsKey(frame)) byFrame[frame] = grid
            }
            out[skin] = byFrame
        }
        return out
    }
}

/** The animations, the same in app and island. */
enum class SpriteAnim {
    idle, sad, sleep, eat, play, love, bath, melt, zap, confused, wave,
    celebrate, stretch, sulk, hide, curious, blush, meet;

    /**
     * The single frame that best shows this animation when it can't move.
     * Idle changes pose with every update so it doesn't look frozen.
     */
    fun posterIndex(at: Instant, calendar: SlimyCalendar = SlimyCalendar.current): Int = when (this) {
        idle -> intArrayOf(0, 1, 3, 5)[calendar.minute(at) % 4]
        play, celebrate -> 1
        meet -> 5
        else -> 0
    }

    companion object {
        val allCases: List<SpriteAnim> get() = entries

        /** The looping animation for a mood. */
        fun of(mood: Mood): SpriteAnim = enumOf<SpriteAnim>(mood.name) ?: idle

        /** The animation for a reaction; null for `none`. */
        fun of(reaction: Reaction): SpriteAnim? =
            if (reaction == Reaction.none) null else enumOf<SpriteAnim>(reaction.name)
    }
}

/**
 * Puts an accessory onto a frame, the same way the generator does for the
 * island fonts (tools/make_slime.py, place_accessory).
 */
object AccessoryPlacer {
    fun place(sprite: AccessorySprite, frame: List<String>, anchor: List<Int>): List<String> {
        val w = SlimeSprites.width
        val h = SlimeSprites.height
        val grid = Array(h) { CharArray(w) { '.' } }
        fun put(x: Int, y: Int, c: Char) {
            if (x in 0 until w && y in 0 until h) grid[y][x] = c
        }
        val cx = (w - 1) / 2 + 1 // round(11.5) in Python rounds to 12
        val top = anchor[0]
        val ey = anchor[1]
        val neck = anchor[2]
        val look = anchor[3]
        val dx = if (anchor.size > 4) anchor[4] else 0 // the meet animation slides sideways
        when (sprite.kind) {
            "hat" -> {
                val x0 = cx - (sprite.rows.firstOrNull()?.length ?: 0) / 2 + dx
                val y0 = top - sprite.rows.size + 1
                for ((dy, row) in sprite.rows.withIndex()) {
                    for ((col, ch) in row.withIndex()) if (ch != '.') put(x0 + col, y0 + dy, ch)
                }
            }
            "glasses" -> {
                val x0 = cx - (sprite.rows.firstOrNull()?.length ?: 0) / 2 + look + dx
                for ((dy, row) in sprite.rows.withIndex()) {
                    for ((col, ch) in row.withIndex()) if (ch != '.') put(x0 + col, ey - 1 + dy, ch)
                }
            }
            "scarf" -> {
                fun span(y: Int): Pair<Int, Int>? {
                    if (y < 0 || y >= frame.size) return null
                    val chars = frame[y]
                    val xs = chars.indices.filter { chars[it] in "bsk" }
                    val a = xs.firstOrNull() ?: return null
                    return a to xs.last()
                }
                for ((i, y) in listOf(neck, neck + 1).withIndex()) {
                    val (a, b) = span(y) ?: continue
                    for (x in a..b) put(x, y, if ((x + i) % 3 == 0) 'b' else 'a')
                }
                span(neck)?.let { (a, _) ->
                    put(a + 3, neck + 2, 'a')
                    put(a + 3, neck + 3, 'b')
                }
            }
        }
        return grid.map { String(it) }
    }
}
